import java.text.DecimalFormat;
import java.util.Scanner;
public class JAverageDouble {
	public static void main(String[] args) {
		//Khatwa 1: Ta'reef al-mutaghayyirat allati nahtaajuha li-hadha al-barnamaj
		double total = 0;
		int count = 0;
		double average;
		///Khatwa 2: Qira'at al-raqam al-awwal allazi yadkhuluhu al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil raqam: ");
		double num = scan.nextDouble();
		//Khatwa 3: A'amil al-raqm al-mudkhal thumma istaqbil wa a'mal al-mu'amala lil-arqam al-taliya ma damma al-raqm ghayr salbi; w'illa qif
		while (num >= 0.0) {
			count++;
			total += num;
			System.out.println("Al-majmou al-hali huwa " + total+", adad = "+count);
			System.out.println("Adkhil raqam: ");
			num = scan.nextDouble();
		}
		scan.close();
		//Khatwa 4: Ihsib wa atba' al-mutawassit lil-arqam al-mudkhalah min al-mustakhdim
		if (count == 0) {
			System.out.println("Lam yadkhul ay arqam.");
		} else {
			average = total / count;
			DecimalFormat fmt = new DecimalFormat("0.###");
			System.out.println("Al-mutawassit huwa " + fmt.format(average));
		}
	}
}
